import{nativeAtlasTile,pixelSignature,atlasPatchCell}from'./reconstruction-ground.js';
import{sourceBlock}from'./source-cells.js';
// Repair only a recorded, unchanged patch from the affected reviewed recipe.
// Never replace metatile 648 globally: it is valid counter artwork elsewhere.
export function upgradeReviewedFloorPatches(project,map,atlas,templates){
 let changed=0,skipped=0;const r=map.rom;if(!r)return{changed,skipped};const hashes=new Map();for(let id=0;id<r.attributes.length;id++){const hash=pixelSignature(nativeAtlasTile(atlas,id));if(!hashes.has(hash))hashes.set(hash,id);}
 const cellHash=t=>t&&r.layerAtlasIds.includes(t.a)&&t.size===16?pixelSignature(nativeAtlasTile(atlas,t.sy/16*16+t.sx/16)):null;
 for(const a of map.nativeAssemblies||[]){const recovery=a.reconstruction,latest=templates.find(t=>t.id===a.templateId);if(!recovery||recovery.floorRepairRevision===1||!latest?.backgroundRepairs?.some(v=>v.floorSignatures))continue;
 const rect=recovery.sourceRect;if(!rect)continue;const source=Array.from({length:a.w*a.h},(_,i)=>{const word=sourceBlock(map,rect.x+i%a.w,rect.y+Math.floor(i/a.w));return word===null||word===undefined?null:pixelSignature(nativeAtlasTile(atlas,word&1023));}),same=(a,b)=>JSON.stringify(a)===JSON.stringify(b),old=recovery.backgroundRepairs?.find(v=>same(v.sourceHashes,source)),next=latest.backgroundRepairs.find(v=>v.floorSignatures&&same(v.sourceHashes,source));if(!old||!next)continue;if(old.floorSignatures){recovery.floorRepairRevision=1;continue;}if(!recovery.underlayApproved&&!recovery.relocated){recovery.backgroundRepairs=structuredClone(latest.backgroundRepairs);const template=project.romObjects?.find(t=>t.id===a.templateId);if(template)template.backgroundRepairs=structuredClone(latest.backgroundRepairs);recovery.floorRepairRevision=1;continue;}
 const differences=next.backgroundHashes.map((hash,i)=>hash!==old.backgroundHashes[i]?i:-1).filter(i=>i>=0);if(differences.some(i=>Math.floor(i/a.w)<next.wallRows||old.backgroundHashes[i]!==pixelSignature(nativeAtlasTile(atlas,648))||next.backgroundHashes[i]!==pixelSignature(nativeAtlasTile(atlas,642))))continue;if(!differences.length){recovery.floorRepairRevision=1;continue;}
 const data=recovery.relocated?null:a.before,indices=Array.from({length:a.w*a.h},(_,i)=>(rect.y+Math.floor(i/a.w))*map.width+rect.x+i%a.w),layers=data?.layers||map.layers;
 let safe=next.backgroundHashes.every(hash=>hashes.has(hash));for(let i=0;i<a.w*a.h&&safe;i++){const j=data?i:indices[i],tile=layers.ground?.[j];if(cellHash(tile)!==old.backgroundHashes[i])safe=false;for(let p=0;p<r.layerAtlasIds.length;p++){const t=layers[['ground','details','overhead'][p]]?.[j];if(!t||t.a!==r.layerAtlasIds[p]||cellHash(t)!==old.backgroundHashes[i])safe=false;}}
 if(!data&&safe)for(const i of indices){const x=i%map.width,y=Math.floor(i/map.width);if((map.nativeAssemblies||[]).some(o=>x>=o.x&&y>=o.y&&x<o.x+o.w&&y<o.y+o.h)||(map.objects||[]).some(o=>x>=o.x&&y>=o.y&&x<o.x+o.w&&y<o.y+o.h)||map.wallCells?.[i])safe=false;}
 if(safe){for(const i of differences){const j=data?i:indices[i],cell=atlasPatchCell(map,hashes.get(next.backgroundHashes[i]),{});for(const key of ['ground','details','overhead'])layers[key][j]=cell.layers[key];changed++;}recovery.backgroundRepairs=structuredClone(latest.backgroundRepairs);const t=project.romObjects?.find(t=>t.id===a.templateId);if(t)t.backgroundRepairs=structuredClone(latest.backgroundRepairs);recovery.floorRepairRevision=1;}else{skipped++;recovery.floorRepairNeedsReview=true;}
 }return{changed,skipped};
}
